using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonFacilityLayout
    {
        static void Place(Component c,float x,float y,float w,float h){var r=c.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
        static void Bind(Button b,UnityEngine.Events.UnityAction action){b.onClick=new Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(b.onClick,action);b.onClick.SetPersistentListenerState(0,UnityEngine.Events.UnityEventCallState.EditorAndRuntime);}
        static T Copy<T>(T source,Transform root,Transform target) where T:Component=>target.Find(AnimationUtility.CalculateTransformPath(source.transform,root)).GetComponent<T>();
        static Text Summary(Text notice){var parent=notice.transform.parent;var old=parent.Find("Facility Summary");if(old!=null)Object.DestroyImmediate(old.gameObject);var text=Object.Instantiate(notice,parent);text.name="Facility Summary";Place(text,24,62,892,74);text.fontSize=18;text.alignment=TextAnchor.UpperLeft;text.text="現在の状態と資金";return text;}
        static void Scroll(Text details,float y,float height){var scroll=details.transform.parent.parent.GetComponent<ScrollRect>();Place(scroll,24,y,892,height);Place(scroll.viewport,6,6,862,height-12);scroll.verticalScrollbar.GetComponent<RectTransform>().sizeDelta=new Vector2(12,height-12);details.rectTransform.sizeDelta=new Vector2(862,details.rectTransform.sizeDelta.y);details.fontSize=18;}
        static void Standard(Text title,Text details,Text notice,Button close,Button confirm,Button cancel,GameObject confirmation,Button[] actions){Place(title,24,16,892,40);Scroll(details,148,330);Place(notice,24,488,892,50);notice.fontSize=15;int n=actions.Length;float width=n==1?580:n==2?284:186;for(int i=0;i<n;i++)Place(actions[i],24+i*(width+12),550,width,40);Place(close,616,550,300,40);close.GetComponentInChildren<Text>().text="閉じる";confirm.GetComponentInChildren<Text>().text="確定する";cancel.GetComponentInChildren<Text>().text="取り消す";confirmation.transform.SetAsLastSibling();confirmation.SetActive(false);}
        public static void RefreshIfReady(){var p=Object.FindObjectOfType<ContentPreview>();if(p==null || p.GetComponent<PythonExpansionPanel>()?.panel==null || p.GetComponent<PythonRestSpacePanel>()?.panel==null || p.GetComponent<PythonWaitingAreaPanel>()?.panel==null || p.GetComponent<PythonSeatEquipmentPanel>()?.panel==null || p.GetComponent<PythonHousingPanel>()?.panel==null || p.GetComponent<PythonMenuPanel>()?.entries==null)return;Build();}
        [MenuItem("Cat Cafe/開発用/UI再生成/設備・増設画面の整理",false,36)]
        public static void Build()
        {
            var scene=EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=Object.FindObjectOfType<ContentPreview>();
            var expansion=preview.GetComponent<PythonExpansionPanel>();expansion.summary=Summary(expansion.notice);Standard(expansion.title,expansion.details,expansion.notice,expansion.close,expansion.confirm,expansion.cancel,expansion.confirmation,new[]{expansion.proceed});Bind(expansion.proceed,expansion.Choose);Bind(expansion.close,expansion.Close);Bind(expansion.confirm,expansion.Confirm);Bind(expansion.cancel,expansion.Cancel);
            var rest=preview.GetComponent<PythonRestSpacePanel>();rest.summary=Summary(rest.notice);Standard(rest.title,rest.details,rest.notice,rest.close,rest.confirm,rest.cancel,rest.confirmation,new[]{rest.purchase,rest.upgrade,rest.soundproof});Bind(rest.purchase,rest.Purchase);Bind(rest.upgrade,rest.Upgrade);Bind(rest.soundproof,rest.Soundproof);Bind(rest.close,rest.Close);Bind(rest.confirm,rest.Confirm);Bind(rest.cancel,rest.Cancel);
            var waiting=preview.GetComponent<PythonWaitingAreaPanel>();waiting.summary=Summary(waiting.notice);Standard(waiting.title,waiting.details,waiting.notice,waiting.close,waiting.confirm,waiting.cancel,waiting.confirmation,new[]{waiting.purchase,waiting.upgrade});Bind(waiting.purchase,waiting.Purchase);Bind(waiting.upgrade,waiting.Upgrade);Bind(waiting.close,waiting.Close);Bind(waiting.confirm,waiting.Confirm);Bind(waiting.cancel,waiting.Cancel);
            var equipment=preview.GetComponent<PythonSeatEquipmentPanel>();equipment.summary=Summary(equipment.notice);Standard(equipment.title,equipment.details,equipment.notice,equipment.close,equipment.confirm,equipment.cancel,equipment.confirmation,new[]{equipment.purchase,equipment.equip,equipment.remove});Place(equipment.seatSelector,24,148,284,40);Place(equipment.kindSelector,320,148,596,40);Place(equipment.itemSelector,24,196,892,40);Scroll(equipment.details,248,230);Bind(equipment.purchase,equipment.Purchase);Bind(equipment.equip,equipment.Equip);Bind(equipment.remove,equipment.Remove);Bind(equipment.close,equipment.Close);Bind(equipment.confirm,equipment.Confirm);Bind(equipment.cancel,equipment.Cancel);Bind(equipment.seatSelector,equipment.NextSeat);Bind(equipment.kindSelector,equipment.NextKind);Bind(equipment.itemSelector,equipment.NextItem);
            var housing=preview.GetComponent<PythonHousingPanel>();var card=housing.close.transform.parent;Place(card.GetComponent<RectTransform>(),170,8,940,600);var title=card.Find("Title").GetComponent<Text>();
            var oldScroll=housing.details.transform.parent.parent.GetComponent<ScrollRect>();if(oldScroll==null){var original=housing.details;var source=expansion.details.transform.parent.parent;var clone=Object.Instantiate(source.gameObject,card);clone.name="Facility Details";housing.details=Copy(expansion.details,source,clone.transform);Object.DestroyImmediate(original.gameObject);}
            if(housing.confirmation==null){housing.confirmation=Object.Instantiate(expansion.confirmation,card);housing.confirmation.name="Housing Confirmation";housing.confirmationText=Copy(expansion.confirmationText,expansion.confirmation.transform,housing.confirmation.transform);housing.confirm=Copy(expansion.confirm,expansion.confirmation.transform,housing.confirmation.transform);housing.cancel=Copy(expansion.cancel,expansion.confirmation.transform,housing.confirmation.transform);}
            Place(housing.confirmation.GetComponent<RectTransform>(),0,0,940,600);Place(housing.confirmationText,40,58,860,410);Place(housing.confirm,100,480,340,44);Place(housing.cancel,500,480,340,44);
            housing.summary=Summary(housing.notice);Standard(title,housing.details,housing.notice,housing.close,housing.confirm,housing.cancel,housing.confirmation,new[]{housing.expand});Bind(housing.expand,housing.Expand);Bind(housing.close,housing.Close);Bind(housing.confirm,housing.Confirm);Bind(housing.cancel,housing.Cancel);Bind(housing.open,housing.Open);
            var menu=preview.GetComponent<PythonMenuPanel>();if(menu.housingEntry==null){menu.housingEntry=Object.Instantiate(menu.entries[4],menu.entries[4].transform.parent);menu.housingEntry.name="Housing Entry";}Bind(menu.housingEntry,menu.OpenHousing);menu.housingEntry.gameObject.SetActive(false);
            foreach(var panel in new[]{expansion.panel,rest.panel,waiting.panel,equipment.panel,housing.panel})panel.SetActive(false);
            EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Debug.Log("CAT_CAFE_FACILITY_LAYOUT_OK");
        }
    }
}
